import React, { useState } from 'react';
import axios from 'axios'; // axios'ı ekliyoruz
import './Contact.css';
import PageTitle from '../PageTitle';

function Contact() {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    subject: '',
    message: '',
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.post('/api/notifications', formData); // Backend'e POST isteği gönder
      alert('Mesajınız gönderildi!');
      setFormData({
        name: '',
        email: '',
        subject: '',
        message: '',
      });
    } catch (error) {
      console.error('Mesaj gönderilirken hata oluştu:', error);
      alert('Mesaj gönderilemedi.');
    }
  };

  return (
    <>
      <PageTitle title='İletişim'/>
      <div>
        <div className="video-container">
          <video autoPlay muted loop>
            <source src="/beehiveloop.mp4" type="video/mp4" />
            Your browser does not support the video tag.
          </video>
          <div className="video-overlay">
            <h1>Welcome to Our Website</h1>
            <p>Discover our products and services</p>
            <a href="/urunumuz">
              <button className="anasayfabuton">Ürünümüz</button>
            </a>
          </div>
        </div>

        <div className="contact-page">
          <div className="contact-info-container">
            <div className="contact-info-left">
              <h2>Şirket Bilgileri</h2>
              <p><strong>Şirket İsmi:</strong> Beehive Inc.</p>
              <p><strong>Adres:</strong> 123 Bee Street, Honey City</p>
              <p><strong>Telefon:</strong> +90 123 456 7890</p>
            </div>
            <div className="contact-info-right">
              <h2>İletişim Formu</h2>
              <form onSubmit={handleSubmit}>
                <label>
                  İsim:
                  <input
                    type="text"
                    name="name"
                    value={formData.name}
                    onChange={handleChange}
                    required
                  />
                </label>
                <label>
                  E-posta:
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleChange}
                    required
                  />
                </label>
                <label>
                  Konu:
                  <input
                    type="text"
                    name="subject"
                    value={formData.subject}
                    onChange={handleChange}
                    required
                  />
                </label>
                <label>
                  Mesaj:
                  <textarea
                    name="message"
                    rows="5"
                    value={formData.message}
                    onChange={handleChange}
                    required
                  ></textarea>
                </label>
                <button type="submit">Mesajı Gönder</button>
              </form>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}

export default Contact;
